# %% ../nbs/08_smoke.ipynb #09a5b566
import numpy as np

from .config import tiny_config
from .model import build, compile_model, to_device


# %% ../nbs/08_smoke.ipynb #5f3055ed
def main() -> None:
    config = tiny_config()
    model = build(config)
    batch = 2
    compiled = compile_model(model, batch=batch)
    spectrogram = np.random.default_rng(0).standard_normal(
        (batch, config.time_bins, config.n_mels, config.in_chans)
    ).astype(np.float32)
    tokens = np.asarray(compiled(to_device(model, spectrogram)).to_numpy())
    expected = (batch, config.num_patches, config.embed_dim)
    if tokens.shape != expected:
        raise SystemExit(f"tokens shape {tokens.shape}, expected {expected}")
    if not np.isfinite(tokens).all():
        raise SystemExit("outputs are not finite")
    print("smoke ok", "tokens", tuple(tokens.shape))


# %% ../nbs/08_smoke.ipynb #d39928b6
if __name__ == "__main__":
    main()

